                return defaultPort;
            }
            double port = Tsonic.CSharp.Js.Globals.Number(configured);
            if (!Tsonic.CSharp.Js.Number.isInteger(port) || port < 1 || port > 65535)
            {
                throw new System.InvalidOperationException("PROOF_PORT must be an integer from 1 through 65535.");
            }
            return port;
