                        return;
                      }
                      await loadPost(id);
                    });
                  }

                  el("create").addEventListener("click", async () => {
                    el("error").textContent = "";
                    el("status").textContent = "Creating...";
                    const title = el("title").value;
                    const content = el("content").value;
                    const res = await api("/api/posts", {
