import type { i32 } from "@tsonic/mojo/types.js";
export { typedLocationProof } from "./typed-locations.js";
export { nestedInvocationErrorProof } from "./error-domains.js";
export { numericOperatorsProof, floatingBitwiseProof } from "./numeric.js";
export { rawPointerSame, rawPointerHash, nativeByteCopy, nativeByteOffset } from "./pointers.js";
export { optionalRegionProof } from "./optional-regions.js";
export { callablePrefixProof, contextualPrefixProof } from "./callable-prefix.js";
export { returnedCallableProof, nestedCaptureProof } from "./returned-callables.js";
export { mutationResultProof } from "./mutation-results.js";
export { memberNamesProof } from "./member-names.js";
export { bigintValuesProof, bigintErrorProof } from "./bigint-values.js";
export { staticMethodValuesProof } from "./static-method-values.js";
export { unionFieldMutationsProof } from "./union-field-mutations.js";

interface Pair {
  left: i32;
  right: i32;
}

enum Mode {
  Off,
  On = 4,
}

class Counter {
  value: i32 = 0;

  increment(): i32 {
    this.value += 1;
    return this.value;
  }
}

function identity<T>(value: T): T {
  return value;
}

function selectedMode(): Mode {
  return Mode.On;
}

export function languageProof(): i32 {
  const pair: Pair = { left: 3, right: 4 };
  const { left, right } = pair;
  const values: i32[] = [left, right, 5];
  const [head, ...tail] = values;
  let total: i32 = head;
  for (const value of tail) {
    total += value;
  }
  const counter = new Counter();
  counter.value = total;
  if (selectedMode() === Mode.Off) {
    return 0;
  }
  return identity<i32>(counter.increment()) + 4;
}

export function nestedFinallyProof(fail: boolean): i32 {
  let result: i32 = 0;
  try {
    try {
      if (fail) throw new Error("expected");
      result += 1;
    } catch {
      result += 2;
    }
  } finally {
    result += 3;
  }
  return result;
}

export function bigintValuesProof(): boolean {
  const seed = 1234567890123456789012345678901234567890n;
  let value = seed;
  const before = value++;
  const after = ++value;
  let scalar = 4;
  const scalarBefore = scalar++;
  const scalarAfter = ++scalar;
  return before === seed && after - seed === 2n && value - seed === 2n &&
    scalarBefore === 4 && scalarAfter === 6 && scalar === 6 &&
    seed * 3n / 3n === seed && -7n % 3n === -1n &&
    (2n ** 256n) >> 256n === 1n && (8n << -2n) === 2n &&
    (~0n & 123n) === 123n && `${seed}` === "1234567890123456789012345678901234567890";
}

export function bigintErrorProof(): boolean {
  let caught = 0;
  try { const zero = 0n; const result = 1n / zero; return false; }
  catch { caught++; }
  try { const zero = 0n; const result = 1n % zero; return false; }
  catch { caught++; }
  try { const exponent = -1n; const result = 2n ** exponent; return false; }
  catch { caught++; }
  return caught === 3;
}

function invoke(callback: (value: number, label: string) => number): number {
  return callback(7, "ignored");
}

export function callablePrefixProof(): number {
  let calls = 0;
  const first = (): number => { calls += 1; return 3; };
  const second = (value: number): number => { calls += 1; return value + 2; };
  const selected: (value: number, label: string) => number = second;
  return invoke(first) + invoke(selected) + calls * 100;
}

export function contextualPrefixProof(): number {
  const selected: (value: number, label: string) => number = (value): number => value + 1;
  return selected(8, "ignored");
}

class FirstFailure { value: number = 1; }
class SecondFailure { value: number = 2; }
class ArgumentFailure { value: number = 3; }
class Trace { value: number = 0; }

function selected(value: number, trace: Trace): number {
  trace.value = trace.value * 10 + 2;
  if (value === 1) throw new FirstFailure();
  if (value === 2) throw new SecondFailure();
  return value;
}

function argument(value: number, trace: Trace): number {
  trace.value = trace.value * 10 + 1;
  if (value === 3) throw new ArgumentFailure();
  if (value < 0) return selected(-value, trace);
  return value;
}

