from std.collections import List
from tsonic_node.filesystem import exists, read_text_file_encoded
from tsonic_node.path import join, normalize, resolve


def load_text(path: String) raises Error -> String:
    return read_text_file_encoded(path, "utf8")


def read_fixture(path: String) raises Error -> String:
    var normalized: String = normalize(path)
    if exists(normalized):
        return load_text(normalized)
    return "missing"


def path_collection_proof() raises Error -> Bool:
    var parts: List[String] = ["alpha", "beta"]
    var _binary_left: Bool = join(List[String]()) == "."
    var _logical_value: Bool = (
        _binary_left and join(["alpha", "beta"]) == "alpha/beta"
    )
    if _logical_value:
        var _rest_values: List[String] = List[String]()
        for _rest_item in parts:
            _rest_values.append(_rest_item.copy())
        _rest_values.append("..")
        _rest_values.append("gamma")
        _logical_value = join(_rest_values) == "alpha/gamma"
    return _logical_value and resolve(["/alpha", "beta"]) == "/alpha/beta"

from tsonic_node.buffer import Buffer, buffer_from_string
from tsonic_node.crypto import (
    create_hash,
    create_hmac,
    random_bytes,
    random_uuid,
)
from tsonic_node.process import version
from tsonic_node.stream import stdin
from tsonic_runtime import source_string_length


def crypto_provider_proof() raises Error -> Bool:
    var key: Buffer = buffer_from_string("Jefe")
    var hash: String = (
        create_hash("sha256")
        .update_string(
            "abc",
        )
        .digest()
        .to_string("hex")
    )
    var mac: String = (
        create_hmac("sha256", key)
        .update_string(
            "what do ya want for nothing?",
        )
        .digest("hex")
    )
    var _binary_left: Bool = (
        hash
        == "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
    ) and (
        mac
        == "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843"
    )
    var _binary_left_2: Bool = _binary_left and random_bytes(
        Float64(32)
    ).js_length() == Float64(32)
    var _binary_left_3: Bool = _binary_left_2 and source_string_length(
        random_uuid()
    ) == Float64(36)
    var _binary_left_4: Bool = _binary_left_3 and not stdin().is_paused()
    var _binary_left_5: Bool = _binary_left_4 and not stdin().is_paused()
    var _logical_value: Bool = _binary_left_5 and version() == "tsonic-mojo"
    if _logical_value:
        var _binary_left_6: String = version()
        _logical_value = _binary_left_6 == version()
    return _logical_value
